const longEnough = (pw, min = 8) => pw.length >= min
const hasDigit = (pw) => /[0-9]/.test(pw)
const hasUpper = (pw) => pw !== pw.toLowerCase()
const hasSymbol = (pw) => /[!@#$%&*?]/.test(pw)
function problems(pw) {
  const out = []
  if (!longEnough(pw)) out.push("Use at least 8 characters")
  if (!hasDigit(pw)) out.push("Add a digit")
  if (!hasUpper(pw)) out.push("Add a capital letter")
  if (!hasSymbol(pw)) out.push("Add a symbol")
  return out
}

const rules = [
  (pw) => pw.length >= 8,
  (pw) => /[0-9]/.test(pw),
  (pw) => pw !== pw.toLowerCase(),
  (pw) => /[!@#$%&*?]/.test(pw),
]
function strength(pw) {
  let passed = 0
  for (const rule of rules) {
    if (rule(pw)) passed++
  }
  if (passed === 4) return "strong"
  if (passed === 3) return "good"
  if (passed === 2) return "fair"
  return "weak"
}

function makeChecker(min) {
  return (pw) => {
    const problems = []
    if (pw.length < min) problems.push(`Use at least ${min} characters`)
    if (!/[0-9]/.test(pw)) problems.push("Add a digit")
    if (pw === pw.toLowerCase()) problems.push("Add a capital letter")
    if (!/[!@#$%&*?]/.test(pw)) problems.push("Add a symbol")
    return { ok: problems.length === 0, problems }
  }
}

